-- ═══════════════════════════════════════════════════════════
-- 0052_food_recettes_import_fiches_bellafood.sql
-- STATUT: PROPOSITION
-- Auteur : Claude Code · Date de rédaction : 2026-10-29
-- Objet : import des 68 fiches recettes transmises par Renée-Lise
--   (dossier "Bella'Food — Fiches recettes complètes"), toutes en
--   statut brouillon, aucune publication. Réutilise food_recettes
--   (schéma déjà vérifié le 29/10, migration 0049) — aucune colonne
--   ajoutée, aucune table créée.
--
-- Avant d'exécuter l'import : lance d'abord cette requête de
-- contrôle (dry-run manuel, comme demandé) pour repérer toute
-- collision de nom avec une recette déjà présente et éventuellement
-- déjà modifiée par toi :
--
--   select id, nom, statut, source
--   from public.food_recettes
--   where nom in (
--     'Poulet boucané','Poulet au lait de coco','Colombo de poulet',
--     'Acras de morue','Beignets de crevettes',
--     'Barquette de frites au poulet boucané','Barquette de frites aux merguez',
--     'Frites','Riz blanc nature','Haricots rouges mijotés',
--     'Bananes plantains frites','Légumes sautés du jour',
--     'Salade fraîche d''accompagnement','Riz au lait de coco','Riz djon-djon',
--     'Gratin de bananes plantains','Sauce chien','Sauce coco aromatisée',
--     'Marinade créole au citron','Sauce citron-miel Bella''Food'
--     -- (liste tronquée pour lisibilité — la clé réelle de
--     -- déduplication est "source", pas le nom : voir plus bas)
--   );
--   → si des lignes ressortent ici, préviens-moi avant de lancer
--     l'import plutôt que de l'exécuter directement : on regarde
--     ensemble si c'est la même recette ou une coïncidence de nom.
--
-- Déduplication réelle, celle qui compte et qui est automatique :
--   chaque fiche importée reçoit source = 'bf_import:<id_import>'
--   (ex. 'bf_import:bf_poulet_boucane'). L'INSERT ci-dessous ignore
--   toute ligne dont le "source" existe déjà en base — rejouer cette
--   migration une seconde fois n'ajoute donc rien (demande explicite
--   du cahier des charges : "seconde exécution n'ajoute aucune fiche
--   supplémentaire"). Si tu modifies une fiche importée après coup,
--   elle n'est jamais écrasée par un nouveau run : la clé "source"
--   empêche la ré-insertion, l'UPDATE n'existe pas dans cette
--   migration.
--
-- Contenu de chaque fiche (tout est conservé, rien n'est inventé) :
--   - Les quantités manquantes restent NULL (jamais remplacées par
--     une moyenne) ; quand une fourchette existait (quantite_min/max)
--     elle est conservée telle quelle dans le JSON de l'ingrédient,
--     à côté de "quantite".
--   - Les notes de chaque fiche rappellent l'origine (archive de
--     production, proposition d'essai, code historique non validé)
--     et la liste des points à vérifier avant toute validation —
--     rien n'est présenté comme une recette validée.
--   - Catégorie (poulet, street_food, accompagnement, riz, salade,
--     sauce, jus, dessert, cake, patisserie, cupcake, entremet,
--     glace, brunch, smoothie, the_glace) choisie à la main pour
--     chacune des 68 fiches, à partir de la catégorie/sous-catégorie
--     du référentiel — pas de "autre" générique.
--   - Les anciennes idées de "05_BACKLOG_HISTORIQUE_NON_IMPORTABLE.md"
--     (blaff, punch tropical, box Bella'Sweet...) et les 5 formules
--     commerciales de "04_FORMULES_COMMERCIALES.json" (3€/6€/12€/8€/25€)
--     ne sont PAS importées ici — le document source lui-même les
--     exclut explicitement ("ne pas les insérer dans food_recettes").
--
-- Impact : additif uniquement, une seule table, idempotent.
-- ═══════════════════════════════════════════════════════════

with donnees as (
  select *
  from jsonb_to_recordset($import$
